<?php $page_title='Master KBLI'; $this->load->view('staff/_layout_start',compact('user','page_title')); $can_edit=in_array($user['role_code'],array('superadmin','admin_dinas'),TRUE); ?>
<section class="staff-hero"><div><span class="staff-kicker">MASTER DATA</span><h1>Klasifikasi KBLI</h1><p>Kode kegiatan ekonomi disimpan menurut versi resmi. Kategori belanja di etalase berada pada master kategori tersendiri.</p></div></section>
<?php $master_tab='kbli';$this->load->view('staff/_master_tabs',compact('master_tab')); ?>
<?php if ($error): ?><div class="alert alert-danger" role="alert"><?= html_escape($error) ?></div><?php endif; ?>
<?php if ($this->input->get('diimpor')): ?><div class="alert alert-success" role="status"><?= (int)$this->input->get('diimpor') ?> kode berhasil diimpor.</div><?php endif; ?>
<section class="staff-panel"><h2>Versi klasifikasi</h2><?php if (!$versions): ?><p>Versi KBLI belum dicatat.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Versi</th><th>Dasar hukum</th><th>Berlaku</th><th>Jumlah kode</th></tr></thead><tbody><?php foreach($versions as $version): ?><tr><td><strong><?= html_escape($version['version_label']) ?></strong><?= $version['is_current']?' · Saat ini':'' ?></td><td><?= html_escape($version['legal_basis']?:'Belum dicatat') ?></td><td><?= html_escape($version['effective_date']?:'Belum dicatat') ?></td><td><?= number_format((int)$version['code_count'],0,',','.') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p>Kode hanya ditampilkan jika sudah diimpor dari data klasifikasi yang diperiksa. Jangan gunakan kategori etalase sebagai kode KBLI.</p></section>
<section class="staff-panel"><h2>Daftar kode</h2><form class="staff-list-filter" method="get" action="<?= site_url('pengelola/master/kbli') ?>"><label>Versi<select class="form-select" name="version"><?php foreach($versions as $version): ?><option value="<?= (int)$version['id'] ?>" <?= $version_id==$version['id']?'selected':'' ?>><?= html_escape($version['version_label']) ?></option><?php endforeach; ?></select></label><label>Cari kode atau judul<input class="form-control" type="search" name="q" maxlength="80" value="<?= html_escape($search) ?>"></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button><a href="<?= site_url('pengelola/master/kbli') ?>">Reset</a></form><p class="staff-list-count"><?= number_format($total,0,',','.') ?> kode</p><?php if (!$rows): ?><p>Belum ada kode pada pilihan ini.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Judul</th><th>Induk</th><th>Versi</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><code><?= html_escape($row['code']) ?></code></td><td><?= html_escape($row['title']) ?></td><td><?= html_escape($row['parent_code']?:'—') ?></td><td><?= html_escape($row['version_label']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/master/kbli'),'params'=>array('version'=>$version_id,'q'=>$search,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
<?php if ($can_edit): ?><section class="staff-panel"><h2>Impor kode CSV</h2><p>Gunakan berkas yang sudah dicocokkan dengan sumber resmi. Kolom wajib: <code>code,title</code>. Kolom opsional: <code>parent_code,description</code>. Kode yang sudah ada pada versi terpilih diperbarui; kode lain tetap tersimpan.</p><form method="post" action="<?= site_url('pengelola/master/kbli/impor') ?>" enctype="multipart/form-data" class="master-form"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label>Versi<select class="form-select" name="version_id" required><?php foreach($versions as $version): ?><option value="<?= (int)$version['id'] ?>" <?= $version_id==$version['id']?'selected':'' ?>><?= html_escape($version['version_label']) ?></option><?php endforeach; ?></select></label><label>Berkas CSV<input class="form-control" type="file" name="kbli_csv" accept=".csv,text/csv" required></label><button class="btn btn-primary" type="submit">Impor kode</button></form></section><section class="staff-panel"><h2>Tambah versi</h2><p>Catat versi dan dasar hukumnya sebelum mengimpor kode. Status versi saat ini ditetapkan setelah kode terverifikasi.</p><form method="post" action="<?= site_url('pengelola/master/kbli/versi') ?>" class="master-form"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label>Label versi<input class="form-control" name="version_label" placeholder="KBLI 2025" pattern="KBLI [0-9]{4}" required></label><label>Dasar hukum<input class="form-control" name="legal_basis" maxlength="255"></label><label>Tanggal berlaku<input class="form-control" type="date" name="effective_date"></label><button class="btn btn-primary" type="submit">Simpan versi</button></form></section><?php endif; ?>
